import math


def binomial_probability(n, k, p):
    """Write a function to compute binomial probability for the given number."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if k < 0 or k > n:
        return 0.0
    coeff = math.comb(n, k)
    return float(coeff * (p ** k) * ((1 - p) ** (n - k)))
